diff --git a/src/hb-raster-draw.cc b/src/hb-raster-draw.cc
index c39583daf..629ba3daa 100644
--- a/src/hb-raster-draw.cc
+++ b/src/hb-raster-draw.cc
@@ -1248,19 +1248,16 @@ cell_add (int32_t *area, int16_t *cover, unsigned width, int col,
 	  int32_t fx0, int32_t fy0, int32_t fx1, int32_t fy1, int32_t wind,
 	  unsigned &x_min, unsigned &x_max)
 {
-  if (unlikely ((unsigned) col >= width))
+  if (unlikely (col < 0))
   {
-    if (unlikely (col < 0))
-    {
-      /* Edge is to the left of the surface.  The winding contribution
-       * still carries into the visible region, so add the cover delta
-       * to column 0.  Area is not added since the edge doesn't cross
-       * column 0's cell. */
-      int32_t dy = fy1 - fy0;
-      cover[0] += (int16_t) (dy * wind);
-      x_min = hb_min (x_min, 0u);
-      x_max = hb_max (x_max, 0u);
-    }
+    /* Edge is to the left of the surface.  The winding contribution
+     * still carries into the visible region, so add the cover delta
+     * to column 0.  Area is not added since the edge doesn't cross
+     * column 0's cell. */
+    int32_t dy = fy1 - fy0;
+    cover[0] += (int16_t) (dy * wind);
+    x_min = hb_min (x_min, 0u);
+    x_max = hb_max (x_max, 0u);
     return;
   }
   int32_t dy = fy1 - fy0;
@@ -1310,10 +1307,12 @@ edge_sweep_row (int32_t                *area,
   int32_t fx1 = x1 & HB_RASTER_PIXEL_MASK;
   int32_t wind = edge.wind;

-  /* Fast path: both endpoints in the same pixel column. */
+  /* Fast path: both endpoints in the same pixel column.  A column at
+   * or past the right edge of the surface contributes nothing. */
   if (cx0 == cx1)
   {
-    cell_add (area, cover, width, cx0 - x_org, fx0, fy0, fx1, fy1, wind, x_min, x_max);
+    if (likely (cx0 - x_org < (int) width))
+      cell_add (area, cover, width, cx0 - x_org, fx0, fy0, fx1, fy1, wind, x_min, x_max);
     return;
   }

@@ -1431,7 +1430,10 @@ edge_sweep_row (int32_t                *area,
     int32_t x_b = (int32_t) hb_clamp ((int64_t) cx0 * HB_RASTER_ONE_PIXEL,
 				      (int64_t) INT32_MIN, (int64_t) INT32_MAX);
     int32_t fy_b = fy0 + (int32_t) ((((int64_t) x_b - (int64_t) x0) * total_dy) / total_dx);
-    cell_add (area, cover, width, cx0 - x_org, fx0, fy0, 0, fy_b, wind, x_min, x_max);
+    /* The edge's first column can lie right of the surface; it
+     * contributes nothing, so enter the walk at the visible window. */
+    if (likely (cx0 <= col_max))
+      cell_add (area, cover, width, cx0 - x_org, fx0, fy0, 0, fy_b, wind, x_min, x_max);

     int32_t cx = cx0 - 1;
     int32_t fy_prev = fy_b;

